/// <reference lib="webworker" />
/**
 * sw.ts — progressive service worker (offline shell + background sync).
 * Registered from main.tsx; in the production Next.js app this is generated by
 * next-pwa/Workbox with the same strategy:
 *   - precache the app shell
 *   - network-first for /api/* with fallback to cache (SWR)
 *   - replay queued mutations when connectivity returns
 */
const CACHE = 'medistream-shell-v1';
const SHELL = ['/', '/index.html', '/src/styles.css'];

self.addEventListener('install', (e: ExtendEvent) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => (self as any).skipWaiting()));
});

self.addEventListener('activate', (e: ExtendEvent) => {
  e.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => (self as any).clients.claim()),
  );
});

self.addEventListener('fetch', (e: FetchEvent2) => {
  const url = new URL(e.request.url);
  if (url.pathname.startsWith('/api/')) {
    // Network first, fall back to cached API response when offline
    e.respondWith(
      fetch(e.request).catch(async () => (await caches.match(e.request)) ?? Response.error()),
    );
    return;
  }
  if (e.request.mode === 'navigate') {
    e.respondWith(fetch(e.request).catch(() => caches.match('/index.html') as Promise<Response>));
  }
});

// Background Sync: flush the offline mutation queue stored by the app.
self.addEventListener('sync', (e: any) => {
  if (e.tag === 'medistream-sync') {
    e.waitUntil(
      (self as any).clients.matchAll({ type: 'window' }).then((clients: any[]) =>
        clients.forEach((c) => c.postMessage({ type: 'FLUSH_SYNC_QUEUE' })),
      ),
    );
  }
});

type ExtendEvent = ExtendableEventLike;
interface ExtendableEventLike {
  waitUntil(p: Promise<any>): void;
}
interface FetchEvent2 {
  request: Request;
  respondWith(r: Promise<Response> | Response): void;
}
declare const self: ServiceWorkerGlobalScope & Record<string, any>;
